-- =============================================================================
-- HAND-WRITTEN additions (Prisma does not model collations or CHECK constraints;
-- neither is reported as schema drift)
-- =============================================================================

-- Secrets and opaque keys compare exactly (the default collation is case-insensitive).
ALTER TABLE `Session` MODIFY `token` VARCHAR(255) NOT NULL COLLATE utf8mb4_bin;
ALTER TABLE `AdminSession` MODIFY `tokenHash` VARCHAR(64) NOT NULL COLLATE utf8mb4_bin;
ALTER TABLE `AdminInvitation` MODIFY `tokenHash` VARCHAR(64) NOT NULL COLLATE utf8mb4_bin;
ALTER TABLE `Verification` MODIFY `identifier` VARCHAR(255) NOT NULL COLLATE utf8mb4_bin;
ALTER TABLE `MediaAsset` MODIFY `storageKey` VARCHAR(191) NOT NULL COLLATE utf8mb4_bin;

-- Integrity checks. Patterns compare in a binary collation so they are case-sensitive.
ALTER TABLE `Review` ADD CONSTRAINT `Review_rating_range` CHECK (`rating` BETWEEN 1 AND 5);
ALTER TABLE `GeoRestriction` ADD CONSTRAINT `GeoRestriction_country_format`
  CHECK ((`countryCode` COLLATE utf8mb4_bin) REGEXP '^[A-Z]{2}$');
ALTER TABLE `Listing` ADD CONSTRAINT `Listing_slug_format`
  CHECK ((`slug` COLLATE utf8mb4_bin) REGEXP '^[a-z0-9]+(-[a-z0-9]+)*$');
ALTER TABLE `Listing` ADD CONSTRAINT `Listing_website_https`
  CHECK ((`websiteUrl` COLLATE utf8mb4_bin) LIKE 'https://%');
ALTER TABLE `Listing` ADD CONSTRAINT `Listing_rating_average_range`
  CHECK (`ratingAverage` >= 0 AND `ratingAverage` <= 5);

-- Not expressible here: MySQL 8 and MariaDB both forbid CHECK constraints on
-- columns that carry foreign-key actions. These rules are enforced by the
-- application and covered by tests/db (see docs/DATABASE.md §3):
--   * GeoRestriction targets exactly one of listingId / categoryId;
--   * a Category is never its own parent.
